-- =============================================================================
-- Migration 0053: K.5 — Integralen bij parameterkrommen
-- =============================================================================
-- Gegenereerd door scripts/k5-content.ts — niet met de hand bewerken.
--
-- Paragraaf K.5. Twee theorieblokken.
-- A: oppervlakte en inhoud van een vlakdeel langs een kromme en een as.
-- B: hetzelfde als de kromme een vlakdeel omsluit.
--
-- Vier clusters, acht vragen per cluster.
--
-- Eigen oefenvragen, geen boekopgaven. Elke integraal wordt nagerekend door
-- src/content/primitieven.test.ts (content/hoofdstuk-k/k5.json): de
-- primitieve naar de parameter, en de exacte uitkomst via de grenzen.
--
-- Alleen toevoegen: geen DELETE, DROP of ALTER, en geen UPDATE op bestaande
-- vragen. De UPDATEs zetten theory_block_id op de topics van K.5 A en K.5 B,
-- en alleen als die koppeling er nog niet staat. Twee keer draaien voegt
-- niets dubbel toe.
--
--   • 1 hoofdstuk, 4 topics, 4 clusters
--   • 32 vragen met elk 4 stappen (128 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('k', $ksql$K — Voortgezette integraalrekening$ksql$, 4, 12, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 1b. Paragraaf en theorieblok
INSERT INTO public.paragraphs (chapter_id, site, slug, label, title, order_index)
SELECT c.id, 'integralen', 'k5', 'K.5', 'Integralen bij parameterkrommen', 6
FROM public.chapters c
WHERE c.slug = 'k' AND c.site = 'integralen'
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.theory_blocks (paragraph_id, site, slug, letter, title, order_index)
SELECT p.id, 'integralen', 'k5a', 'A', 'Oppervlakten en inhouden bij parameterkrommen', 1
FROM public.paragraphs p
WHERE p.slug = 'k5' AND p.site = 'integralen'
ON CONFLICT (slug) DO NOTHING;

INSERT INTO public.theory_blocks (paragraph_id, site, slug, letter, title, order_index)
SELECT p.id, 'integralen', 'k5b', 'B', 'Oppervlakten en inhouden van omsloten vlakdelen', 2
FROM public.paragraphs p
WHERE p.slug = 'k5' AND p.site = 'integralen'
ON CONFLICT (slug) DO NOTHING;


-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'k' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('k5a_oppervlakte', $ksql$Oppervlakte langs een parameterkromme$ksql$, 33, 'toepassingen'),
  ('k5a_inhoud', $ksql$Inhoud bij een parameterkromme$ksql$, 34, 'toepassingen'),
  ('k5b_oppervlakte', $ksql$Oppervlakte van een gesloten kromme$ksql$, 35, 'toepassingen'),
  ('k5b_inhoud', $ksql$Inhoud bij een gesloten kromme$ksql$, 36, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$Oppervlakte met de assen$ksql$, 1),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$Wentelen om een as$ksql$, 1),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$Oppervlakte van een omsloten vlakdeel$ksql$, 1),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$Inhoud van een omwentelingslichaam$ksql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
INSERT INTO public.questions_new
  (site, topic_id, cluster_id, latex_body, answer, latex_answer, difficulty, order_index, is_ai_generated, answer_alternatives)
SELECT 'integralen', t.id, cl.id, v.latex_body, v.answer, v.latex_answer, v.difficulty, v.order_index, false, v.alternatives
FROM (VALUES
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$4/3$ksql$, $ksql$\dfrac{4}{3}$ksql$, 1, 1, ARRAY[]::text[]),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 3t - t^{2} \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$9/2$ksql$, $ksql$\dfrac{9}{2}$ksql$, 1, 2, ARRAY[]::text[]),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$9$ksql$, $ksql$9$ksql$, 1, 3, ARRAY[]::text[]),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$16/3$ksql$, $ksql$\dfrac{16}{3}$ksql$, 2, 4, ARRAY[]::text[]),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4t - t^{2} \\ y(t) = t^{2} \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$128/3$ksql$, $ksql$\dfrac{128}{3}$ksql$, 2, 5, ARRAY[]::text[]),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 4 \\ y(t) = t \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$32/3$ksql$, $ksql$\dfrac{32}{3}$ksql$, 2, 6, ARRAY[]::text[]),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 4 - t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$64/3$ksql$, $ksql$\dfrac{64}{3}$ksql$, 3, 7, ARRAY[]::text[]),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le \tfrac{1}{2}\pi$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$pi$ksql$, $ksql$\pi$ksql$, 3, 8, ARRAY[$ksql$1*pi$ksql$, $ksql$4*pi/4$ksql$]::text[]),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(8/3)*pi$ksql$, $ksql$\dfrac{8}{3}\pi$ksql$, 1, 1, ARRAY[$ksql$8*pi/3$ksql$, $ksql$8/3 pi$ksql$]::text[]),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2 \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$12*pi$ksql$, $ksql$12\pi$ksql$, 1, 2, ARRAY[$ksql$12pi$ksql$]::text[]),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$36*pi$ksql$, $ksql$36\pi$ksql$, 1, 3, ARRAY[$ksql$36pi$ksql$]::text[]),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2t - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(16/15)*pi$ksql$, $ksql$\dfrac{16}{15}\pi$ksql$, 2, 4, ARRAY[$ksql$16*pi/15$ksql$, $ksql$16/15 pi$ksql$]::text[]),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(81/10)*pi$ksql$, $ksql$\dfrac{81}{10}\pi$ksql$, 2, 5, ARRAY[$ksql$81*pi/10$ksql$]::text[]),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4 - t \\ y(t) = t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(64/3)*pi$ksql$, $ksql$\dfrac{64}{3}\pi$ksql$, 2, 6, ARRAY[$ksql$64*pi/3$ksql$, $ksql$64/3 pi$ksql$]::text[]),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(512/15)*pi$ksql$, $ksql$\dfrac{512}{15}\pi$ksql$, 3, 7, ARRAY[$ksql$512*pi/15$ksql$]::text[]),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 1 \\ y(t) = t \end{cases}$ met $0 \le t \le 1$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(8/15)*pi$ksql$, $ksql$\dfrac{8}{15}\pi$ksql$, 3, 8, ARRAY[$ksql$8*pi/15$ksql$]::text[]),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$pi$ksql$, $ksql$\pi$ksql$, 1, 1, ARRAY[]::text[]),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$4*pi$ksql$, $ksql$4\pi$ksql$, 1, 2, ARRAY[$ksql$4pi$ksql$]::text[]),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$2*pi$ksql$, $ksql$2\pi$ksql$, 1, 3, ARRAY[$ksql$2pi$ksql$]::text[]),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$6*pi$ksql$, $ksql$6\pi$ksql$, 2, 4, ARRAY[$ksql$6pi$ksql$]::text[]),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$8/15$ksql$, $ksql$\dfrac{8}{15}$ksql$, 2, 5, ARRAY[]::text[]),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 2t^{3} - 2t \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$16/15$ksql$, $ksql$\dfrac{16}{15}$ksql$, 2, 6, ARRAY[]::text[]),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, symmetrisch in de $y$-as. Bereken exact de totale oppervlakte van deze vlakdelen.$ksql$, $ksql$8/3$ksql$, $ksql$\dfrac{8}{3}$ksql$, 3, 7, ARRAY[]::text[]),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 9t - t^{3} \\ y(t) = t^{2} \end{cases}$ met $-3 \le t \le 3$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, $ksql$648/5$ksql$, $ksql$\dfrac{648}{5}$ksql$, 3, 8, ARRAY[]::text[]),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(4/3)*pi$ksql$, $ksql$\dfrac{4}{3}\pi$ksql$, 1, 1, ARRAY[$ksql$4*pi/3$ksql$, $ksql$4/3 pi$ksql$]::text[]),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(32/3)*pi$ksql$, $ksql$\dfrac{32}{3}\pi$ksql$, 1, 2, ARRAY[$ksql$32*pi/3$ksql$]::text[]),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(8/3)*pi$ksql$, $ksql$\dfrac{8}{3}\pi$ksql$, 1, 3, ARRAY[$ksql$8*pi/3$ksql$]::text[]),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(1/12)*pi$ksql$, $ksql$\dfrac{1}{12}\pi$ksql$, 2, 4, ARRAY[$ksql$pi/12$ksql$, $ksql$1/12 pi$ksql$]::text[]),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 3t - 3t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(3/4)*pi$ksql$, $ksql$\dfrac{3}{4}\pi$ksql$, 2, 5, ARRAY[$ksql$3*pi/4$ksql$, $ksql$3/4 pi$ksql$]::text[]),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 3\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$24*pi$ksql$, $ksql$24\pi$ksql$, 2, 6, ARRAY[$ksql$24pi$ksql$]::text[]),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, allebei symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als deze vlakdelen om de $x$-as wentelen. Bereken exact de inhoud van $L$.$ksql$, $ksql$(16/15)*pi$ksql$, $ksql$\dfrac{16}{15}\pi$ksql$, 3, 7, ARRAY[$ksql$16*pi/15$ksql$]::text[]),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, $ksql$(64/105)*pi$ksql$, $ksql$\dfrac{64}{105}\pi$ksql$, 3, 8, ARRAY[$ksql$64*pi/105$ksql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. De kromme staat rechts van de $y$-as en $y$ stijgt, dus $O(V) = \displaystyle\int x\,\mathrm{d}y$. Die integraal is positief omdat $x \ge 0$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$y(t) = t$, dus $\mathrm{d}y = \mathrm{d}t$. Met $t$ van $0$ tot $2$: $O(V) = \displaystyle\int_{0}^{2} (2t - t^{2})\,\mathrm{d}t$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $t^{2} - \tfrac{1}{3}t^{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[t^{2} - \tfrac{1}{3}t^{3}\right]_{0}^{2} = 4 - \tfrac{8}{3} = \tfrac{4}{3}$. De oppervlakte is $\tfrac{4}{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 3t - t^{2} \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. De kromme staat boven de $x$-as en $x$ stijgt, dus $O(V) = \displaystyle\int y\,\mathrm{d}x$. Die integraal is positief omdat $y \ge 0$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 3t - t^{2} \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$x(t) = t$, dus $\mathrm{d}x = \mathrm{d}t$. Met $t$ van $0$ tot $3$: $O(V) = \displaystyle\int_{0}^{3} (3t - t^{2})\,\mathrm{d}t$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 3t - t^{2} \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $\tfrac{3}{2}t^{2} - \tfrac{1}{3}t^{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 3t - t^{2} \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[\tfrac{3}{2}t^{2} - \tfrac{1}{3}t^{3}\right]_{0}^{3} = \tfrac{27}{2} - 9 = \tfrac{9}{2}$. De oppervlakte is $\tfrac{9}{2}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Langs de assen is de integraal $0$. De kromme loopt van de $y$-as naar de $x$-as, van links naar rechts, met $y \ge 0$. Dus $O(V) = \displaystyle\int y\,\mathrm{d}x$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$x(t) = t$ en $t$ loopt van $0$ tot $3$: $O(V) = \displaystyle\int_{0}^{3} (6 - 2t)\,\mathrm{d}t$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $6t - t^{2}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[6t - t^{2}\right]_{0}^{3} = 18 - 9 = 9$. De oppervlakte is $9$. (Het is een rechthoekige driehoek met rechthoekszijden $3$ en $6$.)$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Bij $t = 0$ staat de kromme op de positieve $y$-as, bij $t = 2$ op de positieve $x$-as. Ertussen is $y \ge 0$ en loopt $x$ van links naar rechts, dus $O(V) = \displaystyle\int y\,\mathrm{d}x$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$O(V) = \displaystyle\int_{0}^{2} (4 - t^{2})\,\mathrm{d}t$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $4t - \tfrac{1}{3}t^{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ in het eerste kwadrant wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[4t - \tfrac{1}{3}t^{3}\right]_{0}^{2} = 8 - \tfrac{8}{3} = \tfrac{16}{3}$. De oppervlakte is $\tfrac{16}{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4t - t^{2} \\ y(t) = t^{2} \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Op $[0, 4]$ is $x(t) = t(4 - t) \ge 0$ en stijgt $y$. De kromme begint en eindigt op de $y$-as, dus $O(V) = \displaystyle\int x\,\mathrm{d}y$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4t - t^{2} \\ y(t) = t^{2} \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}y = 2t\,\mathrm{d}t$, dus $O(V) = \displaystyle\int_{0}^{4} (4t - t^{2}) \cdot 2t\,\mathrm{d}t = \displaystyle\int_{0}^{4} (8t^{2} - 2t^{3})\,\mathrm{d}t$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4t - t^{2} \\ y(t) = t^{2} \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $\tfrac{8}{3}t^{3} - \tfrac{1}{2}t^{4}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4t - t^{2} \\ y(t) = t^{2} \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[\tfrac{8}{3}t^{3} - \tfrac{1}{2}t^{4}\right]_{0}^{4} = \tfrac{512}{3} - 128 = \tfrac{128}{3}$. De oppervlakte is $\tfrac{128}{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 4 \\ y(t) = t \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. De kromme ligt links van de $y$-as ($x \le 0$) en loopt van onder naar boven. $\displaystyle\int x\,\mathrm{d}y$ is dan negatief. De oppervlakte is het tegengestelde.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 4 \\ y(t) = t \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}y = \mathrm{d}t$ en $x = t^{2} - 4$, dus $O(V) = -\displaystyle\int_{-2}^{2} (t^{2} - 4)\,\mathrm{d}t = \displaystyle\int_{-2}^{2} (4 - t^{2})\,\mathrm{d}t$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 4 \\ y(t) = t \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $4t - \tfrac{1}{3}t^{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 4 \\ y(t) = t \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[4t - \tfrac{1}{3}t^{3}\right]_{-2}^{2} = \left(8 - \tfrac{8}{3}\right) - \left(-8 + \tfrac{8}{3}\right) = \tfrac{32}{3}$. De oppervlakte is $\tfrac{32}{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 4 - t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Bij $t = 0$ is het punt $(0, 4)$ en bij $t = 4$ het punt $(16, 0)$. Ertussen is $y \ge 0$ en stijgt $x$, dus $O(V) = \displaystyle\int y\,\mathrm{d}x$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 4 - t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}x = 2t\,\mathrm{d}t$, dus $O(V) = \displaystyle\int_{0}^{4} (4 - t) \cdot 2t\,\mathrm{d}t = \displaystyle\int_{0}^{4} (8t - 2t^{2})\,\mathrm{d}t$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 4 - t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $4t^{2} - \tfrac{2}{3}t^{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 4 - t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[4t^{2} - \tfrac{2}{3}t^{3}\right]_{0}^{4} = 64 - \tfrac{128}{3} = \tfrac{64}{3}$. De oppervlakte is $\tfrac{64}{3}$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le \tfrac{1}{2}\pi$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Dit is een kwartcirkel met straal $2$ in het eerste kwadrant. Van $t = \tfrac{1}{2}\pi$ naar $t = 0$ loopt $x$ van links naar rechts en is $y \ge 0$, dus $O(V) = \displaystyle\int y\,\mathrm{d}x$ met die volgorde van $t$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le \tfrac{1}{2}\pi$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}x = -2\sin(t)\,\mathrm{d}t$. $\displaystyle\int_{\pi/2}^{0} 2\sin(t) \cdot (-2\sin(t))\,\mathrm{d}t = \displaystyle\int_{0}^{\pi/2} 4\sin^{2}(t)\,\mathrm{d}t$. Gebruik $\sin^{2}(t) = \tfrac{1}{2}(1 - \cos(2t))$, dus de integrand is $2 - 2\cos(2t)$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le \tfrac{1}{2}\pi$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $2t - \sin(2t)$.$ksql$),
  ('k5a_oppervlakte', 'k5a_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le \tfrac{1}{2}\pi$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[2t - \sin(2t)\right]_{0}^{\pi/2} = \pi$. De oppervlakte is $\pi$. (Een kwart van de cirkel met straal $2$ heeft oppervlakte $\tfrac{1}{4} \cdot \pi \cdot 2^{2} = \pi$.)$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Wentelen om de $x$-as geeft de inhoud $\pi \displaystyle\int y^{2}\,\mathrm{d}x$. De kromme loopt van links naar rechts en $y \ge 0$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$y = t$ en $\mathrm{d}x = \mathrm{d}t$, met $t$ van $0$ tot $2$: $I(L) = \displaystyle\int_{0}^{2} \pi t^{2}\,\mathrm{d}t$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi \cdot \tfrac{1}{3}t^{3}$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = t \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\left[\tfrac{1}{3}\pi t^{3}\right]_{0}^{2} = \tfrac{8}{3}\pi$. De inhoud is $\tfrac{8}{3}\pi$. (Het lichaam is een kegel met straal $2$ en hoogte $2$.)$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2 \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Wentelen om de $x$-as geeft $\pi \displaystyle\int y^{2}\,\mathrm{d}x$. Hier is $y$ constant $2$, en $x$ loopt van links naar rechts.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2 \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$I(L) = \displaystyle\int_{0}^{3} \pi \cdot 2^{2}\,\mathrm{d}t = \displaystyle\int_{0}^{3} 4\pi\,\mathrm{d}t$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2 \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $4\pi t$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2 \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de $x$-as en de lijnen $x = 0$ en $x = 3$. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\left[4\pi t\right]_{0}^{3} = 12\pi$. De inhoud is $12\pi$. (Het lichaam is een cilinder met straal $2$ en hoogte $3$.)$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Wentelen om de $x$-as geeft $\pi \displaystyle\int y^{2}\,\mathrm{d}x$. Op dit stuk is $y \ge 0$ en loopt $x$ van links naar rechts.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$I(L) = \displaystyle\int_{0}^{3} \pi(6 - 2t)^{2}\,\mathrm{d}t = \displaystyle\int_{0}^{3} \pi(36 - 24t + 4t^{2})\,\mathrm{d}t$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi\left(36t - 12t^{2} + \tfrac{4}{3}t^{3}\right)$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 6 - 2t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\pi\left[36t - 12t^{2} + \tfrac{4}{3}t^{3}\right]_{0}^{3} = \pi(108 - 108 + 36) = 36\pi$. De inhoud is $36\pi$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2t - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Wentelen om de $x$-as geeft $\pi \displaystyle\int y^{2}\,\mathrm{d}x$. De boog ligt boven de $x$-as en $x$ stijgt.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2t - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$(2t - t^{2})^{2} = 4t^{2} - 4t^{3} + t^{4}$, dus $I(L) = \displaystyle\int_{0}^{2} \pi(4t^{2} - 4t^{3} + t^{4})\,\mathrm{d}t$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2t - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi\left(\tfrac{4}{3}t^{3} - t^{4} + \tfrac{1}{5}t^{5}\right)$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 2t - t^{2} \end{cases}$ met $0 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\pi\left[\tfrac{4}{3}t^{3} - t^{4} + \tfrac{1}{5}t^{5}\right]_{0}^{2} = \pi\left(\tfrac{32}{3} - 16 + \tfrac{32}{5}\right) = \pi \cdot \tfrac{16}{15} = \tfrac{16}{15}\pi$. De inhoud is $\tfrac{16}{15}\pi$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Wentelen om de $y$-as geeft $\pi \displaystyle\int x^{2}\,\mathrm{d}y$. Op $[0, 3]$ is $x \ge 0$ en stijgt $y$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$\mathrm{d}y = \mathrm{d}t$ en $x = 3t - t^{2}$, dus $I(L) = \displaystyle\int_{0}^{3} \pi(3t - t^{2})^{2}\,\mathrm{d}t = \displaystyle\int_{0}^{3} \pi(9t^{2} - 6t^{3} + t^{4})\,\mathrm{d}t$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi\left(3t^{3} - \tfrac{3}{2}t^{4} + \tfrac{1}{5}t^{5}\right)$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3t - t^{2} \\ y(t) = t \end{cases}$ met $0 \le t \le 3$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\pi\left[3t^{3} - \tfrac{3}{2}t^{4} + \tfrac{1}{5}t^{5}\right]_{0}^{3} = \pi\left(81 - \tfrac{243}{2} + \tfrac{243}{5}\right) = \pi \cdot \tfrac{81}{10} = \tfrac{81}{10}\pi$. De inhoud is $\tfrac{81}{10}\pi$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4 - t \\ y(t) = t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Wentelen om de $y$-as geeft $\pi \displaystyle\int x^{2}\,\mathrm{d}y$. Hier is $x$ de afstand tot de $y$-as, en $y$ stijgt van $0$ tot $4$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4 - t \\ y(t) = t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$x = 4 - t$ en $\mathrm{d}y = \mathrm{d}t$: $I(L) = \displaystyle\int_{0}^{4} \pi(4 - t)^{2}\,\mathrm{d}t = \displaystyle\int_{0}^{4} \pi(16 - 8t + t^{2})\,\mathrm{d}t$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4 - t \\ y(t) = t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi\left(16t - 4t^{2} + \tfrac{1}{3}t^{3}\right)$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 4 - t \\ y(t) = t \end{cases}$ met $0 \le t \le 4$. Het vlakdeel $V$ wordt ingesloten door $K$, de positieve $x$-as en de positieve $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\pi\left[16t - 4t^{2} + \tfrac{1}{3}t^{3}\right]_{0}^{4} = \pi\left(64 - 64 + \tfrac{64}{3}\right) = \tfrac{64}{3}\pi$. De inhoud is $\tfrac{64}{3}\pi$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Wentelen om de $x$-as geeft $\pi \displaystyle\int y^{2}\,\mathrm{d}x$. Op $[-2, 2]$ is $y \ge 0$ en loopt $x$ van links naar rechts.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$(4 - t^{2})^{2} = 16 - 8t^{2} + t^{4}$, dus $I(L) = \displaystyle\int_{-2}^{2} \pi(16 - 8t^{2} + t^{4})\,\mathrm{d}t$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi\left(16t - \tfrac{8}{3}t^{3} + \tfrac{1}{5}t^{5}\right)$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t \\ y(t) = 4 - t^{2} \end{cases}$ met $-2 \le t \le 2$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$De integrand is even, dus het verschil van de grenzen is twee keer de waarde bij $t = 2$: $2\pi\left(32 - \tfrac{64}{3} + \tfrac{32}{5}\right) = 2\pi \cdot \tfrac{256}{15} = \tfrac{512}{15}\pi$. De inhoud is $\tfrac{512}{15}\pi$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 1 \\ y(t) = t \end{cases}$ met $0 \le t \le 1$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. De kromme ligt links van de $y$-as. De straal bij het wentelen om de $y$-as is de afstand tot die as, dus $|x| = 1 - t^{2}$. De inhoud is $\pi \displaystyle\int x^{2}\,\mathrm{d}y$, en $y$ stijgt.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 1 \\ y(t) = t \end{cases}$ met $0 \le t \le 1$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$x^{2} = (t^{2} - 1)^{2} = t^{4} - 2t^{2} + 1$ en $\mathrm{d}y = \mathrm{d}t$: $I(L) = \displaystyle\int_{0}^{1} \pi(t^{4} - 2t^{2} + 1)\,\mathrm{d}t$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 1 \\ y(t) = t \end{cases}$ met $0 \le t \le 1$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi\left(\tfrac{1}{5}t^{5} - \tfrac{2}{3}t^{3} + t\right)$.$ksql$),
  ('k5a_inhoud', 'k5a_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} - 1 \\ y(t) = t \end{cases}$ met $0 \le t \le 1$. Het vlakdeel $V$ wordt ingesloten door $K$ en de $y$-as. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\pi\left[\tfrac{1}{5}t^{5} - \tfrac{2}{3}t^{3} + t\right]_{0}^{1} = \pi\left(\tfrac{1}{5} - \tfrac{2}{3} + 1\right) = \pi \cdot \tfrac{8}{15} = \tfrac{8}{15}\pi$. De inhoud is $\tfrac{8}{15}\pi$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Bij een omsloten vlakdeel dat in positieve richting wordt omgelopen, is $O(V) = \displaystyle\int x\,\mathrm{d}y$. Hier loopt $t$ van $0$ tot $2\pi$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}y = \cos(t)\,\mathrm{d}t$, dus $O(V) = \displaystyle\int_{0}^{2\pi} \cos(t) \cdot \cos(t)\,\mathrm{d}t = \displaystyle\int_{0}^{2\pi} \cos^{2}(t)\,\mathrm{d}t$. Met $\cos^{2}(t) = \tfrac{1}{2}(1 + \cos(2t))$ wordt dat $\displaystyle\int_{0}^{2\pi} \tfrac{1}{2}(1 + \cos(2t))\,\mathrm{d}t$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $\tfrac{1}{2}t + \tfrac{1}{4}\sin(2t)$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[\tfrac{1}{2}t + \tfrac{1}{4}\sin(2t)\right]_{0}^{2\pi} = \pi$. De oppervlakte is $\pi$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Positieve richting, dus $O(V) = \displaystyle\int x\,\mathrm{d}y$ met $t$ van $0$ tot $2\pi$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}y = 2\cos(t)\,\mathrm{d}t$, dus $O(V) = \displaystyle\int_{0}^{2\pi} 2\cos(t) \cdot 2\cos(t)\,\mathrm{d}t = \displaystyle\int_{0}^{2\pi} 4\cos^{2}(t)\,\mathrm{d}t = \displaystyle\int_{0}^{2\pi} (2 + 2\cos(2t))\,\mathrm{d}t$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $2t + \sin(2t)$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[2t + \sin(2t)\right]_{0}^{2\pi} = 4\pi$. De oppervlakte is $4\pi$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Positieve richting, dus $O(V) = \displaystyle\int x\,\mathrm{d}y$ met $t$ van $0$ tot $2\pi$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}y = \cos(t)\,\mathrm{d}t$, dus $O(V) = \displaystyle\int_{0}^{2\pi} 2\cos(t) \cdot \cos(t)\,\mathrm{d}t = \displaystyle\int_{0}^{2\pi} (1 + \cos(2t))\,\mathrm{d}t$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $t + \tfrac{1}{2}\sin(2t)$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[t + \tfrac{1}{2}\sin(2t)\right]_{0}^{2\pi} = 2\pi$. De oppervlakte is $2\pi$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Positieve richting, dus $O(V) = \displaystyle\int x\,\mathrm{d}y$ met $t$ van $0$ tot $2\pi$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}y = 2\cos(t)\,\mathrm{d}t$, dus $O(V) = \displaystyle\int_{0}^{2\pi} 3\cos(t) \cdot 2\cos(t)\,\mathrm{d}t = \displaystyle\int_{0}^{2\pi} 6\cos^{2}(t)\,\mathrm{d}t = \displaystyle\int_{0}^{2\pi} (3 + 3\cos(2t))\,\mathrm{d}t$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $3t + \tfrac{3}{2}\sin(2t)$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 3\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$\left[3t + \tfrac{3}{2}\sin(2t)\right]_{0}^{2\pi} = 6\pi$. De oppervlakte is $6\pi$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. De kromme begint en eindigt in $(0, 0)$. Ze wordt in positieve richting omgelopen, dus $O(V) = \displaystyle\int x\,\mathrm{d}y$ met $t$ van $-1$ tot $1$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}y = (1 - 3t^{2})\,\mathrm{d}t$, dus $O(V) = \displaystyle\int_{-1}^{1} (1 - t^{2})(1 - 3t^{2})\,\mathrm{d}t = \displaystyle\int_{-1}^{1} (1 - 4t^{2} + 3t^{4})\,\mathrm{d}t$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $t - \tfrac{4}{3}t^{3} + \tfrac{3}{5}t^{5}$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$De integrand is even, dus het verschil van de grenzen is twee keer de waarde bij $t = 1$: $2\left(1 - \tfrac{4}{3} + \tfrac{3}{5}\right) = 2 \cdot \tfrac{4}{15} = \tfrac{8}{15}$. De oppervlakte is $\tfrac{8}{15}$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 2t^{3} - 2t \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Begin- en eindpunt zijn allebei $(1, 0)$. Positieve richting, dus $O(V) = \displaystyle\int x\,\mathrm{d}y$ met $t$ van $-1$ tot $1$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 2t^{3} - 2t \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$y(t) = 2(t^{3} - t)$, dus $\mathrm{d}y = 2(3t^{2} - 1)\,\mathrm{d}t$. Dan $O(V) = \displaystyle\int_{-1}^{1} t^{2} \cdot 2(3t^{2} - 1)\,\mathrm{d}t = \displaystyle\int_{-1}^{1} (6t^{4} - 2t^{2})\,\mathrm{d}t$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 2t^{3} - 2t \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $\tfrac{6}{5}t^{5} - \tfrac{2}{3}t^{3}$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 2t^{3} - 2t \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$2\left(\tfrac{6}{5} - \tfrac{2}{3}\right) = 2 \cdot \tfrac{8}{15} = \tfrac{16}{15}$. De oppervlakte is $\tfrac{16}{15}$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, symmetrisch in de $y$-as. Bereken exact de totale oppervlakte van deze vlakdelen.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. De twee lussen zijn even groot. Eén lus hoort bij $t$ van $0$ tot $\pi$. Omdat de parameter daar de lus de andere kant op loopt, neem je het tegengestelde van $\displaystyle\int x\,\mathrm{d}y$ en tel je de tweede lus erbij.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, symmetrisch in de $y$-as. Bereken exact de totale oppervlakte van deze vlakdelen.$ksql$, 1, $ksql$$\mathrm{d}y = 2\cos(2t)\,\mathrm{d}t$. De totale oppervlakte is $2 \cdot \left(-\displaystyle\int_{0}^{\pi} \sin(t) \cdot 2\cos(2t)\,\mathrm{d}t\right) = \displaystyle\int_{0}^{\pi} -4\sin(t)\cos(2t)\,\mathrm{d}t$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, symmetrisch in de $y$-as. Bereken exact de totale oppervlakte van deze vlakdelen.$ksql$, 2, $ksql$Schrijf $\cos(2t) = 1 - 2\sin^{2}(t)$. Dan is de integrand $-4\sin(t) + 8\sin^{3}(t)$. Een primitieve is $-4\cos(t) + \tfrac{8}{3}\cos^{3}(t)$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, symmetrisch in de $y$-as. Bereken exact de totale oppervlakte van deze vlakdelen.$ksql$, 3, $ksql$$\left[-4\cos(t) + \tfrac{8}{3}\cos^{3}(t)\right]_{0}^{\pi} = \left(4 - \tfrac{8}{3}\right) - \left(-4 + \tfrac{8}{3}\right) = \tfrac{8}{3}$. De totale oppervlakte is $\tfrac{8}{3}$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 9t - t^{3} \\ y(t) = t^{2} \end{cases}$ met $-3 \le t \le 3$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Bij $t = -3$ en bij $t = 3$ is het punt $(0, 9)$, en bij $t = 0$ het punt $(0, 0)$. Positieve richting, dus $O(V) = \displaystyle\int x\,\mathrm{d}y$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 9t - t^{3} \\ y(t) = t^{2} \end{cases}$ met $-3 \le t \le 3$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 1, $ksql$$\mathrm{d}y = 2t\,\mathrm{d}t$, dus $O(V) = \displaystyle\int_{-3}^{3} (9t - t^{3}) \cdot 2t\,\mathrm{d}t = \displaystyle\int_{-3}^{3} (18t^{2} - 2t^{4})\,\mathrm{d}t$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 9t - t^{3} \\ y(t) = t^{2} \end{cases}$ met $-3 \le t \le 3$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 2, $ksql$Een primitieve is $6t^{3} - \tfrac{2}{5}t^{5}$.$ksql$),
  ('k5b_oppervlakte', 'k5b_oppervlakte', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 9t - t^{3} \\ y(t) = t^{2} \end{cases}$ met $-3 \le t \le 3$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Bereken exact de oppervlakte van $V$.$ksql$, 3, $ksql$$2\left(6 \cdot 27 - \tfrac{2}{5} \cdot 243\right) = 2\left(162 - \tfrac{486}{5}\right) = 2 \cdot \tfrac{324}{5} = \tfrac{648}{5}$. De oppervlakte is $\tfrac{648}{5}$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. $V$ is de eenheidscirkel, symmetrisch in de $x$-as. Wentelen om de $x$-as geeft een bol. De straal is $y$ van de bovenste helft, dus $I(L) = \pi \displaystyle\int y^{2}\,\mathrm{d}x$ langs die helft, van links naar rechts.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$De bovenste helft van rechts naar links is $t$ van $0$ tot $\pi$, met $\mathrm{d}x = -\sin(t)\,\mathrm{d}t$. Omdraaien geeft $I(L) = \displaystyle\int_{0}^{\pi} \pi\sin^{3}(t)\,\mathrm{d}t$. Schrijf $\sin^{3}(t) = (1 - \cos^{2}(t))\sin(t)$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi\left(-\cos(t) + \tfrac{1}{3}\cos^{3}(t)\right)$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\pi\left[\left(1 - \tfrac{1}{3}\right) - \left(-1 + \tfrac{1}{3}\right)\right] = \pi \cdot \tfrac{4}{3} = \tfrac{4}{3}\pi$. De inhoud is $\tfrac{4}{3}\pi$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Cirkel met straal $2$, symmetrisch in de $x$-as. $I(L) = \pi \displaystyle\int y^{2}\,\mathrm{d}x$ langs de bovenste helft, van links naar rechts.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$y = 2\sin(t)$ en van links naar rechts wordt de factor $-\mathrm{d}x$ positief: $I(L) = \displaystyle\int_{0}^{\pi} \pi \cdot 4\sin^{2}(t) \cdot 2\sin(t)\,\mathrm{d}t = \displaystyle\int_{0}^{\pi} 8\pi\sin^{3}(t)\,\mathrm{d}t$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $8\pi\left(-\cos(t) + \tfrac{1}{3}\cos^{3}(t)\right)$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 2\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$8\pi \cdot \tfrac{4}{3} = \tfrac{32}{3}\pi$. De inhoud is $\tfrac{32}{3}\pi$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. De kromme is symmetrisch in de $x$-as. $I(L) = \pi \displaystyle\int y^{2}\,\mathrm{d}x$ langs de bovenste helft, van links naar rechts.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$y = \sin(t)$ en $\mathrm{d}x = -2\sin(t)\,\mathrm{d}t$ op de bovenste helft. Van links naar rechts: $I(L) = \displaystyle\int_{0}^{\pi} \pi\sin^{2}(t) \cdot 2\sin(t)\,\mathrm{d}t = \displaystyle\int_{0}^{\pi} 2\pi\sin^{3}(t)\,\mathrm{d}t$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $2\pi\left(-\cos(t) + \tfrac{1}{3}\cos^{3}(t)\right)$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = \sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$2\pi \cdot \tfrac{4}{3} = \tfrac{8}{3}\pi$. De inhoud is $\tfrac{8}{3}\pi$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Door de symmetrie in de $x$-as is de straal de $y$ van de bovenste helft ($t$ van $0$ tot $1$). Daar loopt $x$ van $1$ naar $0$, dus van rechts naar links. Voor de inhoud draai je de grenzen om: $I(L) = \pi \displaystyle\int y^{2}\,\mathrm{d}x$ van links naar rechts.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$y = t - t^{3}$ en $\mathrm{d}x = -2t\,\mathrm{d}t$. Van $t = 1$ naar $t = 0$ wordt dat $\displaystyle\int_{0}^{1} \pi \cdot 2t(t - t^{3})^{2}\,\mathrm{d}t = \displaystyle\int_{0}^{1} \pi(2t^{3} - 4t^{5} + 2t^{7})\,\mathrm{d}t$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi\left(\tfrac{1}{2}t^{4} - \tfrac{2}{3}t^{6} + \tfrac{1}{4}t^{8}\right)$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\pi\left(\tfrac{1}{2} - \tfrac{2}{3} + \tfrac{1}{4}\right) = \pi \cdot \tfrac{1}{12} = \tfrac{1}{12}\pi$. De inhoud is $\tfrac{1}{12}\pi$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 3t - 3t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Symmetrisch in de $x$-as. Op de bovenste helft, $t$ van $0$ tot $1$, stijgt $x$ van $0$ naar $1$. Dus $I(L) = \pi \displaystyle\int_{0}^{1} y^{2} x'(t)\,\mathrm{d}t$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 3t - 3t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$y = 3(t - t^{3})$ en $x'(t) = 2t$, dus $y^{2} x'(t) = 18t^{3} - 36t^{5} + 18t^{7}$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 3t - 3t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve van $\pi$ keer die veelterm is $\pi\left(\tfrac{9}{2}t^{4} - 6t^{6} + \tfrac{9}{4}t^{8}\right)$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = t^{2} \\ y(t) = 3t - 3t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en is symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\pi\left(\tfrac{9}{2} - 6 + \tfrac{9}{4}\right) = \pi \cdot \tfrac{3}{4} = \tfrac{3}{4}\pi$. De inhoud is $\tfrac{3}{4}\pi$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 3\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Symmetrisch in de $x$-as. $I(L) = \pi \displaystyle\int y^{2}\,\mathrm{d}x$ langs de bovenste helft, van links naar rechts.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 3\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$y = 3\sin(t)$ en $|\mathrm{d}x| = 2\sin(t)\,\mathrm{d}t$ op $[0, \pi]$ na het omdraaien: $I(L) = \displaystyle\int_{0}^{\pi} \pi \cdot 9\sin^{2}(t) \cdot 2\sin(t)\,\mathrm{d}t = \displaystyle\int_{0}^{\pi} 18\pi\sin^{3}(t)\,\mathrm{d}t$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 3\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $18\pi\left(-\cos(t) + \tfrac{1}{3}\cos^{3}(t)\right)$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 2\cos(t) \\ y(t) = 3\sin(t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit het vlakdeel $V$ in. Het lichaam $L$ ontstaat als $V$ om de $x$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$18\pi \cdot \tfrac{4}{3} = 24\pi$. De inhoud is $24\pi$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, allebei symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als deze vlakdelen om de $x$-as wentelen. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. Elke lus is symmetrisch in de $x$-as, en de lussen zijn even groot. Voor één lus neem je de bovenste helft, $t$ van $0$ tot $\tfrac{1}{2}\pi$: daar stijgt $x$. De totale inhoud is twee keer $\pi \displaystyle\int y^{2}\,\mathrm{d}x$ over die helft.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, allebei symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als deze vlakdelen om de $x$-as wentelen. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$y = \sin(2t) = 2\sin(t)\cos(t)$ en $\mathrm{d}x = \cos(t)\,\mathrm{d}t$. Twee lussen geven $\displaystyle\int_{0}^{\pi/2} 8\pi\sin^{2}(t)\cos^{3}(t)\,\mathrm{d}t$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, allebei symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als deze vlakdelen om de $x$-as wentelen. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Schrijf $\cos^{2}(t) = 1 - \sin^{2}(t)$ en stel de kern $g(t) = \sin(t)$. Dan is een primitieve $\pi\left(\tfrac{8}{3}\sin^{3}(t) - \tfrac{8}{5}\sin^{5}(t)\right)$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = \sin(t) \\ y(t) = \sin(2t) \end{cases}$ met $0 \le t \le 2\pi$. $K$ sluit twee even grote vlakdelen in, allebei symmetrisch in de $x$-as. Het lichaam $L$ ontstaat als deze vlakdelen om de $x$-as wentelen. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$$\pi\left(\tfrac{8}{3} - \tfrac{8}{5}\right) = \pi \cdot \tfrac{16}{15} = \tfrac{16}{15}\pi$. De inhoud is $\tfrac{16}{15}\pi$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 0, $ksql$Hier spelen deel 1 en deel 2 van de driedeling: eerst het vlakdeel vertalen naar een integraal, dan die integraal exact uitrekenen. De kromme raakt de $y$-as alleen in het begin- en eindpunt en ligt verder rechts daarvan. In positieve richting is de inhoud bij wentelen om de $y$-as $\pi \displaystyle\int x^{2}\,\mathrm{d}y$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 1, $ksql$$x^{2} = (1 - t^{2})^{2}$ en $\mathrm{d}y = (1 - 3t^{2})\,\mathrm{d}t$, dus $I(L) = \displaystyle\int_{-1}^{1} \pi(1 - 5t^{2} + 7t^{4} - 3t^{6})\,\mathrm{d}t$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 2, $ksql$Een primitieve is $\pi\left(t - \tfrac{5}{3}t^{3} + \tfrac{7}{5}t^{5} - \tfrac{3}{7}t^{7}\right)$.$ksql$),
  ('k5b_inhoud', 'k5b_inhoud', $ksql$De kromme $K$ is gegeven door $\begin{cases} x(t) = 1 - t^{2} \\ y(t) = t - t^{3} \end{cases}$ met $-1 \le t \le 1$. $K$ sluit het vlakdeel $V$ in en wordt in positieve richting omgelopen. Het lichaam $L$ ontstaat als $V$ om de $y$-as wentelt. Bereken exact de inhoud van $L$.$ksql$, 3, $ksql$Twee keer de waarde bij $t = 1$: $2\pi\left(1 - \tfrac{5}{3} + \tfrac{7}{5} - \tfrac{3}{7}\right) = 2\pi \cdot \tfrac{32}{105} = \tfrac{64}{105}\pi$. De inhoud is $\tfrac{64}{105}\pi$.$ksql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Topics aan het theorieblok koppelen
-- Alleen de topics van dit blok, en alleen als de koppeling er nog niet staat.
UPDATE public.topics_new AS t
SET theory_block_id = b.id
FROM (VALUES
  ('k5a_oppervlakte', 'k5a'),
  ('k5a_inhoud', 'k5a')
) AS v(topic_slug, block_slug)
JOIN public.theory_blocks b ON b.slug = v.block_slug AND b.site = 'integralen'
WHERE t.slug = v.topic_slug
  AND t.site = 'integralen'
  AND t.theory_block_id IS DISTINCT FROM b.id;

DO $blok$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
  FROM public.topics_new t
  JOIN public.theory_blocks b ON b.id = t.theory_block_id
  WHERE t.site = 'integralen'
    AND b.slug = 'k5a'
    AND t.slug IN ('k5a_oppervlakte', 'k5a_inhoud');
  IF n <> 2 THEN
    RAISE EXCEPTION 'Theorieblok k5a hoort 2 topics te hebben, gevonden %', n;
  END IF;
END $blok$;

-- 6b. Topics van theorieblok B koppelen
UPDATE public.topics_new AS t
SET theory_block_id = b.id
FROM (VALUES
  ('k5b_oppervlakte', 'k5b'),
  ('k5b_inhoud', 'k5b')
) AS v(topic_slug, block_slug)
JOIN public.theory_blocks b ON b.slug = v.block_slug AND b.site = 'integralen'
WHERE t.slug = v.topic_slug
  AND t.site = 'integralen'
  AND t.theory_block_id IS DISTINCT FROM b.id;

DO $blokb$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n
  FROM public.topics_new t
  JOIN public.theory_blocks b ON b.id = t.theory_block_id
  WHERE t.site = 'integralen'
    AND b.slug = 'k5b'
    AND t.slug IN ('k5b_oppervlakte', 'k5b_inhoud');
  IF n <> 2 THEN
    RAISE EXCEPTION 'Theorieblok k5b hoort 2 topics te hebben, gevonden %', n;
  END IF;
END $blokb$;

-- 7. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k5a_oppervlakte' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k5a_oppervlakte' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k5a_oppervlakte hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k5a_inhoud' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k5a_inhoud' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k5a_inhoud hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k5b_oppervlakte' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k5b_oppervlakte' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k5b_oppervlakte hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'k5b_inhoud' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'k5b_inhoud' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster k5b_inhoud hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('k5a_oppervlakte', 'k5a_inhoud', 'k5b_oppervlakte', 'k5b_inhoud');
  IF n <> 128 THEN RAISE EXCEPTION 'Deze topics horen samen 128 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
